window.BANK=window.BANK||{};

BANK['xep-doan-nc']=[
'Lợi ích của việc đọc sách|Sách là người bạn thân thiết của mỗi chúng ta.|Trước hết, đọc sách giúp em hiểu biết thêm về thế giới xung quanh.|Không những thế, sách còn dạy em biết yêu thương và sống tốt hơn.|Vì vậy, em sẽ dành thời gian đọc sách mỗi ngày.',
'Cơn mưa rào mùa hạ|Bầu trời bỗng tối sầm lại, gió thổi ào ào.|Chỉ một lát sau, những hạt mưa to bắt đầu rơi lộp độp.|Mưa mỗi lúc một nặng hạt, trắng xóa cả khoảng sân.|Rồi mưa tạnh hẳn, cây cối như được tắm gội, tươi tắn hẳn lên.',
'Người bạn em quý nhất|Trong lớp, người bạn em quý nhất là Thu.|Thu có dáng người nhỏ nhắn, đôi mắt sáng và nụ cười hiền.|Bạn học giỏi nhưng không bao giờ kiêu căng, luôn sẵn lòng giảng bài cho các bạn.|Em mong tình bạn của chúng em sẽ mãi bền chặt.',
'Vì sao cần bảo vệ rừng|Rừng là lá phổi xanh của Trái Đất.|Rừng cung cấp gỗ, dược liệu và là nơi sinh sống của nhiều loài động vật.|Ngoài ra, rừng còn giúp ngăn lũ lụt, giữ đất, điều hòa khí hậu.|Thế nhưng, nhiều cánh rừng đang bị chặt phá bừa bãi.|Bởi vậy, mỗi chúng ta cần chung tay bảo vệ rừng.',
'Buổi sáng trên cánh đồng|Mặt trời vừa nhô lên sau lũy tre làng.|Những tia nắng đầu tiên trải vàng trên cánh đồng lúa.|Sương sớm còn đọng long lanh trên từng ngọn lá.|Xa xa, các bác nông dân đã bắt đầu một ngày làm việc.',
'Kỉ niệm ngày đầu đi học|Em vẫn nhớ như in ngày đầu tiên đến trường.|Hôm ấy, mẹ dắt tay em đi trên con đường làng quen thuộc.|Đến cổng trường, em bỗng thấy lo sợ và nép sát vào mẹ.|Cô giáo dịu dàng bước ra, cầm tay em dẫn vào lớp.|Từ giây phút ấy, em thấy ngôi trường thật gần gũi.',
'Chú mèo nhà em|Nhà em có nuôi một chú mèo tam thể tên là Mướp.|Mướp có bộ lông mềm mượt với ba màu trắng, đen, vàng.|Đôi mắt của chú tròn xoe, ban đêm sáng long lanh như hai hòn bi ve.|Ban ngày, Mướp thường nằm sưởi nắng; đêm đến, chú lại rình bắt chuột rất giỏi.|Em rất yêu quý chú mèo đáng yêu này.',
'Tác hại của rác thải nhựa|Rác thải nhựa đang là vấn đề nghiêm trọng của nhiều quốc gia.|Chúng phải mất hàng trăm năm mới phân hủy được.|Khi trôi ra biển, rác nhựa khiến nhiều loài sinh vật bị chết.|Do đó, chúng ta nên hạn chế dùng túi ni lông và đồ nhựa dùng một lần.',
'Mẹ của em|Mẹ là người em yêu thương nhất trên đời.|Năm nay mẹ ngoài ba mươi tuổi, mái tóc dài luôn được buộc gọn gàng.|Hằng ngày, mẹ đi làm từ sáng sớm, chiều về lại tất bật lo cơm nước.|Dù mệt, mẹ vẫn dành thời gian kèm em học bài.|Em tự hứa sẽ học thật giỏi để mẹ vui lòng.',
'Cây bàng sân trường|Ở góc sân trường em có một cây bàng cổ thụ.|Mùa xuân, cây bàng đâm những chồi non xanh biếc.|Sang hè, tán lá xòe rộng che mát cả một khoảng sân.|Đến mùa đông, những chiếc lá bàng chuyển sang màu đỏ thắm rồi rụng dần.|Cây bàng đã gắn bó với tuổi học trò của chúng em.',
'Ý kiến về việc học sinh dùng điện thoại|Hiện nay, nhiều học sinh tiểu học được bố mẹ cho dùng điện thoại thông minh.|Điện thoại giúp các em liên lạc với gia đình và tra cứu thông tin khi cần.|Tuy nhiên, nếu dùng quá nhiều, các em dễ bị cận thị và lơ là học tập.|Theo em, học sinh chỉ nên dùng điện thoại khi thật cần thiết và có sự hướng dẫn của người lớn.',
'Phiên chợ Tết|Những ngày giáp Tết, chợ quê em đông vui hơn hẳn.|Từ sáng sớm, người đi chợ đã nườm nượp kéo về.|Hàng hoa rực rỡ sắc màu: đào hồng, cúc vàng, quất trĩu quả.|Hàng lá dong, hàng gạo nếp cũng tấp nập người mua kẻ bán.|Ai đi chợ về cũng mang theo không khí rộn ràng của mùa xuân.',
'Ông em|Ông nội em năm nay đã gần tám mươi tuổi.|Tóc ông đã bạc trắng nhưng dáng ông vẫn còn nhanh nhẹn.|Mỗi sáng, ông dậy sớm tập thể dục rồi ra vườn chăm cây.|Buổi tối, ông thường kể cho em nghe chuyện về những năm tháng chiến đấu.|Em luôn kính yêu và tự hào về ông.',
'Một lần mắc lỗi|Hôm ấy, em lỡ tay làm vỡ chiếc bình hoa của mẹ.|Lúc đầu, em sợ quá nên giấu các mảnh vỡ vào gầm tủ.|Nhưng suốt buổi chiều, em cứ thấy lòng nặng trĩu.|Đến tối, em quyết định kể hết sự thật với mẹ.|Mẹ xoa đầu em và khen em đã biết dũng cảm nhận lỗi.',
'Biển quê em|Quê em ở một làng chài ven biển miền Trung.|Buổi sáng, mặt biển phẳng lặng, xanh biếc như một tấm thảm khổng lồ.|Buổi trưa, nắng chiếu xuống làm mặt biển lấp lánh như dát bạc.|Chiều về, những đoàn thuyền đánh cá nối nhau trở về bến.|Em yêu biển quê em biết bao.',
'Lợi ích của việc tập thể dục|Tập thể dục đều đặn mang lại nhiều lợi ích cho sức khỏe.|Trước tiên, nó giúp cơ thể khỏe mạnh, ít ốm đau.|Bên cạnh đó, tập thể dục còn giúp tinh thần sảng khoái, học tập hiệu quả hơn.|Vì thế, mỗi người nên dành ít nhất ba mươi phút tập luyện mỗi ngày.',
'Đêm trung thu|Đêm rằm tháng Tám, trăng tròn vành vạnh treo trên bầu trời.|Bọn trẻ trong xóm rủ nhau rước đèn ông sao đi khắp ngõ.|Tiếng trống múa lân vang lên rộn rã.|Sau đó, cả xóm quây quần bên mâm cỗ đầy bánh trái.|Đêm trung thu năm ấy để lại trong em biết bao kỉ niệm đẹp.',
'Chú gà trống|Nhà em có một chú gà trống rất oai vệ.|Chú có chiếc mào đỏ chót như bông hoa mào gà.|Bộ lông của chú óng ánh nhiều màu: đỏ, vàng, đen.|Sáng nào chú cũng dõng dạc cất tiếng gáy đánh thức cả nhà.',
'Giờ ra chơi|Tùng! Tùng! Tùng! Tiếng trống báo giờ ra chơi vang lên.|Học sinh các lớp ùa ra sân như đàn ong vỡ tổ.|Chỗ này, các bạn nữ chơi nhảy dây; chỗ kia, các bạn nam say sưa đá cầu.|Tiếng nói, tiếng cười rộn rã cả sân trường.|Hết giờ, mọi người lại nhanh chóng xếp hàng vào lớp.',
'Tán thành việc trồng cây xanh|Em rất tán thành việc trồng thêm cây xanh trong sân trường.|Cây xanh giúp không khí trong lành và tạo bóng mát cho học sinh vui chơi.|Hơn nữa, việc tự tay trồng cây giúp chúng em biết yêu thiên nhiên.|Vì vậy, em mong mỗi lớp sẽ nhận chăm sóc một cây xanh.',
'Cảnh hoàng hôn trên sông|Chiều tà, mặt trời đỏ rực từ từ lặn xuống phía tây.|Ánh hoàng hôn nhuộm hồng cả mặt sông.|Những cánh cò chao liệng tìm về tổ.|Dần dần, bóng tối phủ xuống, mặt sông chỉ còn lấp lánh vài ánh đèn thuyền chài.',
'Bác sĩ trong mắt em|Bác sĩ là một nghề cao quý.|Các bác sĩ ngày đêm chăm sóc, chữa bệnh cho mọi người.|Có những lúc, họ phải làm việc suốt đêm không nghỉ.|Em mơ ước sau này cũng trở thành một bác sĩ giỏi.',
'Ngày hội đọc sách|Sáng thứ bảy, trường em tổ chức Ngày hội đọc sách.|Đầu tiên, các lớp trưng bày những cuốn sách hay ở gian hàng của mình.|Tiếp theo, các bạn đại diện lên giới thiệu cuốn sách yêu thích nhất.|Cuối buổi, nhà trường trao giải cho lớp có gian sách đẹp nhất.|Ngày hội khép lại trong niềm vui của tất cả mọi người.',
'Chiếc cặp sách|Chiếc cặp sách là món quà mẹ tặng em vào năm học mới.|Cặp có màu xanh dương, được may bằng vải dày và rất chắc chắn.|Bên trong có ba ngăn để đựng sách, vở và đồ dùng học tập.|Em luôn giữ gìn cặp cẩn thận như một người bạn thân.',
'Vì sao phải giữ gìn vệ sinh trường lớp|Trường lớp là ngôi nhà thứ hai của mỗi học sinh.|Nếu trường lớp bẩn, chúng ta sẽ dễ mắc bệnh và học tập không hiệu quả.|Ngược lại, trường lớp sạch đẹp giúp chúng ta vui vẻ, thoải mái hơn.|Do vậy, mỗi học sinh cần có ý thức giữ gìn vệ sinh chung.',
'Mùa xuân về|Mùa xuân đến, không khí trở nên ấm áp.|Cây cối đâm chồi nảy lộc, khoác lên mình tấm áo xanh mới.|Những bông hoa đua nhau khoe sắc trong vườn.|Chim chóc ríu rít gọi nhau trên cành cây.|Mùa xuân mang đến cho muôn loài sức sống mới.',
'Lần đầu em tự nấu cơm|Hôm ấy, bố mẹ đi làm về muộn nên em quyết định tự nấu cơm.|Đầu tiên, em vo gạo thật sạch rồi đong nước vừa đủ.|Sau đó, em cắm điện cho nồi cơm và nhặt rau.|Khi bố mẹ về, mâm cơm tuy đơn giản nhưng đã sẵn sàng.|Bố mẹ rất vui và khen em đã biết giúp đỡ gia đình.',
'Cô giáo em|Cô giáo chủ nhiệm lớp em tên là Hương.|Cô có giọng nói dịu dàng và đôi mắt luôn ánh lên vẻ hiền từ.|Mỗi khi chúng em chưa hiểu bài, cô lại kiên nhẫn giảng giải.|Chúng em ai cũng yêu quý cô như mẹ hiền.',
'Hồ Gươm|Hồ Gươm nằm giữa lòng thủ đô Hà Nội.|Mặt hồ xanh biếc như một tấm gương lớn.|Giữa hồ, Tháp Rùa cổ kính soi bóng xuống mặt nước.|Ven hồ, những hàng liễu rủ thướt tha trong gió.|Hồ Gươm là niềm tự hào của người Hà Nội.',
'Không nên vứt rác bừa bãi|Hiện nay, nhiều người vẫn có thói quen vứt rác bừa bãi.|Việc làm đó khiến môi trường bị ô nhiễm và làm mất mĩ quan đường phố.|Rác thải còn là nơi sinh sôi của ruồi muỗi, gây ra nhiều bệnh tật.|Vì thế, mỗi người hãy bỏ rác đúng nơi quy định.',
'Cây hoa hồng nhà em|Trước cửa nhà em có một khóm hoa hồng.|Thân cây có nhiều gai nhọn, lá xanh thẫm có răng cưa.|Mỗi sáng, những nụ hoa hé nở, khoe sắc đỏ thắm.|Hương hồng thơm ngát lan khắp góc sân.',
'Chuyến về quê|Hè vừa rồi, em được bố mẹ cho về quê thăm ông bà.|Vừa đến đầu làng, em đã thấy cây đa cổ thụ quen thuộc.|Ông bà ra tận ngõ đón, ôm em vào lòng.|Những ngày ở quê, em được thả diều, câu cá cùng các anh chị.|Chuyến đi ấy để lại trong em nhiều kỉ niệm khó quên.',
'Tình bạn|Ai cũng cần có bạn bè trong cuộc sống.|Bạn bè cùng ta chia sẻ niềm vui, nỗi buồn.|Khi gặp khó khăn, bạn tốt sẽ luôn ở bên giúp đỡ ta.|Bởi vậy, chúng ta cần biết trân trọng và giữ gìn tình bạn.',
'Bình minh trên biển|Trời vừa hửng sáng, mặt biển còn chìm trong màn sương mỏng.|Phía chân trời, một vầng hồng từ từ nhô lên.|Ánh nắng đầu tiên trải dài trên mặt nước, lấp lánh như những vảy cá bạc.|Những chiếc thuyền đánh cá bắt đầu ra khơi.',
'Bà em|Bà nội em năm nay đã bảy mươi lăm tuổi.|Mái tóc bà bạc trắng như mây, đôi mắt hiền từ sau cặp kính.|Bà thường kể cho em nghe những câu chuyện cổ tích.|Mỗi khi em ốm, bà lại ngồi bên quạt cho em ngủ.|Em yêu bà vô cùng.',
'Nên đi bộ đến trường|Nhà em ở gần trường nên em thường đi bộ đến lớp.|Đi bộ giúp em rèn luyện sức khỏe mỗi ngày.|Ngoài ra, việc này còn góp phần giảm khói bụi từ xe cộ.|Em nghĩ các bạn ở gần trường cũng nên đi bộ như em.',
'Con đường đến trường|Con đường từ nhà đến trường em dài khoảng một cây số.|Hai bên đường là những hàng cây xà cừ cao vút.|Buổi sáng, tiếng chim hót líu lo trên những vòm lá.|Con đường đã trở nên thân thuộc với em suốt những năm tiểu học.',
'Bữa cơm gia đình|Bữa cơm tối là lúc cả nhà em quây quần bên nhau.|Mẹ nấu những món ăn giản dị mà ngon miệng.|Trong bữa ăn, mọi người kể cho nhau nghe chuyện trong ngày.|Tiếng cười nói rộn rã khiến căn nhà ấm áp hơn.',
'Bác lao công|Mỗi sáng sớm, khi mọi người còn say ngủ, bác lao công đã bắt đầu làm việc.|Bác cần mẫn quét từng góc phố.|Dù mưa hay nắng, bác vẫn không nghỉ.|Nhờ có bác, đường phố luôn sạch đẹp.|Em rất biết ơn những người lao công như bác.',
'Cây phượng mùa hè|Khi tiếng ve râm ran, cây phượng sân trường bắt đầu nở hoa.|Những chùm hoa đỏ rực như những đốm lửa trên cành.|Gió thổi, cánh phượng rơi lả tả khắp sân.|Nhìn hoa phượng, chúng em biết mùa thi và mùa chia tay đã đến.',
'Giữ gìn truyền thống uống nước nhớ nguồn|Dân tộc ta có truyền thống uống nước nhớ nguồn từ bao đời nay.|Truyền thống ấy nhắc chúng ta biết ơn những người đi trước.|Mỗi dịp lễ, Tết, chúng em lại cùng gia đình thắp hương tưởng nhớ tổ tiên.|Chúng em sẽ cố gắng học tập để xứng đáng với công lao của cha ông.',
'Trận bóng đá|Chiều thứ sáu, lớp em thi đấu bóng đá với lớp 5B.|Ngay khi tiếng còi khai cuộc vang lên, hai đội đã tấn công dồn dập.|Phút thứ mười, đội bạn ghi bàn trước.|Không nản lòng, đội em đã gỡ hòa rồi ghi thêm bàn thắng.|Kết thúc trận đấu, lớp em thắng với tỉ số hai – một.',
'Cánh diều tuổi thơ|Tuổi thơ em gắn liền với những cánh diều.|Mỗi chiều hè, chúng em lại ra bãi đê thả diều.|Những cánh diều bay cao, chao lượn giữa trời xanh.|Nhìn cánh diều, em như thấy ước mơ của mình bay xa.',
'Ích lợi của cây tre|Cây tre gắn bó thân thiết với người Việt Nam.|Tre cho bóng mát và che chở cho xóm làng.|Thân tre dùng để làm nhà, đan rổ rá, làm đồ chơi.|Tre còn là biểu tượng cho sự kiên cường của dân tộc.',
'Một ngày Chủ nhật|Sáng Chủ nhật, em dậy sớm hơn mọi ngày.|Sau khi tập thể dục, em giúp mẹ dọn dẹp nhà cửa.|Buổi chiều, cả nhà đi dạo ở công viên gần nhà.|Buổi tối, em chuẩn bị sách vở cho tuần học mới.|Đó là một ngày Chủ nhật thật vui và ý nghĩa.',
'Chú bộ đội|Anh trai em là một chú bộ đội biên phòng.|Anh có nước da rám nắng và đôi vai vững chãi.|Ngày đêm, anh cùng đồng đội canh giữ biên cương.|Mỗi lần anh về phép, cả nhà lại vui như Tết.',
'Đồ chơi em thích nhất|Món đồ chơi em thích nhất là chú gấu bông bố mua tặng.|Chú có bộ lông màu nâu mềm mại và đôi mắt đen láy.|Tối nào em cũng ôm chú gấu đi ngủ.|Em luôn giữ chú gấu sạch sẽ và cẩn thận.',
'Mưa phùn mùa xuân|Mùa xuân, những hạt mưa phùn lất phất bay.|Mưa nhỏ như rắc bụi, nhẹ như tơ.|Cây cối được tưới mát, đâm chồi nảy lộc.|Mưa xuân mang lại sức sống cho đất trời.',
'Tiết kiệm nước|Nước là nguồn tài nguyên vô cùng quý giá.|Thế nhưng, nhiều nơi trên thế giới đang thiếu nước sạch.|Vì vậy, chúng ta cần tiết kiệm nước trong sinh hoạt hằng ngày.|Chẳng hạn, khi đánh răng, ta nên khóa vòi nước lại.',
'Lễ chào cờ đầu tuần|Sáng thứ hai, toàn trường tập trung dự lễ chào cờ.|Khi tiếng trống vang lên, mọi người đứng nghiêm trang.|Lá cờ đỏ sao vàng từ từ được kéo lên đỉnh cột.|Cả trường cùng hát vang bài Quốc ca hùng tráng.',
'Ngôi nhà của em|Nhà em là một ngôi nhà nhỏ hai tầng.|Tầng một là phòng khách và bếp, tầng hai là phòng ngủ.|Trước nhà có một khoảnh sân trồng nhiều cây cảnh.|Tuy không rộng nhưng ngôi nhà luôn ấm áp tình thân.',
'Bạn Lan lớp em|Lan là lớp trưởng lớp em.|Bạn có mái tóc dài, đôi mắt sáng và nụ cười tươi.|Lan học giỏi, lại hay giúp đỡ các bạn yếu kém.|Ai trong lớp cũng quý mến Lan.',
'Thăm Văn Miếu – Quốc Tử Giám|Cuối tuần trước, lớp em đi tham quan Văn Miếu – Quốc Tử Giám.|Đầu tiên, chúng em đi qua cổng Văn Miếu cổ kính.|Sau đó, cô hướng dẫn viên dẫn chúng em đến khu bia tiến sĩ.|Cuối cùng, cả lớp chụp ảnh lưu niệm trước Khuê Văn Các.|Chuyến đi giúp em hiểu thêm về truyền thống hiếu học của dân tộc.',
'Chú chó Lu|Nhà em có nuôi một chú chó tên là Lu.|Lu có bộ lông vàng óng và đôi tai vểnh lên rất thính.|Hằng ngày, Lu trông nhà rất cẩn thận.|Khi em đi học về, Lu lại chạy ra mừng quýnh.',
'Không nên thức khuya|Nhiều bạn nhỏ có thói quen thức khuya xem ti vi hoặc chơi điện thoại.|Thức khuya khiến cơ thể mệt mỏi, sáng hôm sau khó tập trung học tập.|Lâu dần, sức khỏe sẽ bị ảnh hưởng nghiêm trọng.|Vì thế, chúng ta nên đi ngủ sớm và dậy sớm.',
'Hoa sen|Đầu mùa hạ, những bông sen bắt đầu nở trong đầm.|Lá sen xanh mướt, to như chiếc nón úp trên mặt nước.|Hoa sen hồng nhạt, nhụy vàng, tỏa hương thơm ngát.|Sen là loài hoa thanh cao, gần bùn mà chẳng hôi tanh mùi bùn.',
'Giúp đỡ bạn bè|Giúp đỡ bạn bè là một việc làm đáng quý.|Khi bạn ốm, ta có thể chép bài giúp bạn.|Khi bạn chưa hiểu bài, ta có thể giảng lại cho bạn.|Những việc làm nhỏ ấy sẽ giúp tình bạn thêm gắn bó.',
'Đêm hè ở quê|Đêm hè ở quê thật yên bình.|Trên bầu trời, hàng ngàn vì sao lấp lánh.|Gió đồng mát rượi thổi qua hiên nhà.|Tiếng ếch nhái kêu râm ran ngoài ruộng.|Em nằm trên chõng tre nghe bà kể chuyện rồi thiếp đi lúc nào không biết.',
'Một tấm gương vượt khó|Bạn Hưng ở lớp em có hoàn cảnh rất khó khăn.|Bố mất sớm, Hưng phải giúp mẹ làm việc nhà và trông em.|Dù vậy, Hưng vẫn luôn đạt danh hiệu học sinh giỏi.|Hưng là tấm gương sáng để chúng em noi theo.',
'Trồng cây trong ngày Tết trồng cây|Sáng hôm ấy, cả trường em tham gia Tết trồng cây.|Đầu tiên, chúng em đào hố và bón phân.|Tiếp đó, chúng em nhẹ nhàng đặt cây con xuống hố.|Cuối cùng, chúng em vun đất và tưới nước cho cây.|Ai cũng mong những cây non sẽ lớn nhanh.',
'Chiếc xe đạp của em|Chiếc xe đạp này là món quà sinh nhật bố tặng em.|Xe màu đỏ tươi, có giỏ phía trước và chuông kêu lanh canh.|Hằng ngày, xe đưa em đến trường.|Em luôn lau chùi xe sạch sẽ sau mỗi lần đi.',
'Tác dụng của tiếng cười|Tiếng cười giúp con người vui vẻ, yêu đời hơn.|Người hay cười thường có sức khỏe tốt.|Hơn thế nữa, tiếng cười còn giúp mọi người gần gũi nhau hơn.|Vậy hãy luôn mỉm cười mỗi ngày.',
'Ngày khai giảng|Sáng ngày 5 tháng 9, sân trường rực rỡ cờ hoa.|Học sinh trong bộ đồng phục mới xếp hàng ngay ngắn.|Thầy hiệu trưởng đọc thư của Chủ tịch nước gửi ngành giáo dục.|Rồi tiếng trống khai trường vang lên giòn giã.|Một năm học mới đã bắt đầu.',
'Đôi bàn tay của mẹ|Đôi bàn tay mẹ không mềm mại như tay các cô diễn viên.|Bàn tay ấy ram ráp, chai sạn vì bao năm làm lụng.|Thế nhưng, chính đôi tay ấy đã nấu cho em những bữa cơm ngon.|Em yêu đôi bàn tay của mẹ biết bao.',
'Ước mơ của em|Ai cũng có những ước mơ cho riêng mình.|Ước mơ của em là trở thành một nhà khoa học.|Em muốn chế tạo ra những chiếc máy giúp người nông dân bớt vất vả.|Để thực hiện ước mơ, ngay từ bây giờ em phải học thật giỏi.',
'Một buổi chiều mưa|Chiều hôm ấy, trời bỗng nổi gió mạnh.|Mây đen kéo đến kín trời.|Một lát sau, mưa ào ào đổ xuống.|Em ngồi bên cửa sổ, ngắm những hạt mưa rơi trên tán lá.',
'Cây xoài trong vườn|Trong vườn nhà em có một cây xoài do ông trồng.|Thân cây to, tán lá rộng che mát cả góc vườn.|Đầu hè, cây ra những chùm hoa vàng nhạt.|Ít lâu sau, những quả xoài xanh lủng lẳng trên cành.|Khi xoài chín, cả nhà lại quây quần thưởng thức.',
'Lễ phép với người lớn|Lễ phép với người lớn là truyền thống tốt đẹp của dân tộc ta.|Khi gặp người lớn, chúng ta cần chào hỏi lễ phép.|Khi người lớn nói, ta cần chú ý lắng nghe.|Như vậy, ta sẽ được mọi người yêu quý.',
'Bức tranh em vẽ|Hôm qua, em vẽ một bức tranh về quê hương.|Ở giữa là cánh đồng lúa chín vàng.|Phía xa là dãy núi xanh và mặt trời đỏ rực.|Em tô màu thật cẩn thận rồi treo bức tranh lên tường.',
'Thầy giáo dạy Thể dục|Thầy giáo dạy Thể dục của trường em tên là Bình.|Thầy có dáng người cao lớn, nước da rám nắng.|Trong giờ học, thầy hướng dẫn chúng em từng động tác.|Nhờ thầy, chúng em ngày càng khỏe mạnh hơn.',
'Mùa thu Hà Nội|Mùa thu, Hà Nội trở nên dịu dàng hơn.|Trời xanh trong, nắng vàng nhạt như mật ong.|Gió heo may se lạnh thổi qua những con phố.|Hương hoa sữa nồng nàn lan khắp các ngõ nhỏ.',
'Học tập chăm chỉ|Học tập là nhiệm vụ quan trọng nhất của học sinh.|Chăm chỉ học tập giúp chúng ta có kiến thức.|Có kiến thức, chúng ta sẽ làm được nhiều việc có ích.|Vì thế, em luôn cố gắng học tập thật chăm chỉ.',
'Cảnh chợ quê|Chợ quê em họp vào buổi sáng.|Từ tờ mờ sáng, các bà các mẹ đã gánh hàng ra chợ.|Hàng rau xanh mướt, hàng cá tươi rói bày la liệt.|Tiếng mời chào, mặc cả rộn ràng cả một góc làng.|Gần trưa, chợ vãn dần, mọi người lại tất bật ra về.',
'Món quà ý nghĩa|Sinh nhật năm nay, em nhận được một món quà đặc biệt.|Đó là cuốn sổ do chính tay chị gái làm tặng em.|Bìa cuốn sổ được trang trí bằng những bông hoa khô xinh xắn.|Bên trong, chị viết những lời chúc thật ấm áp.|Em sẽ giữ gìn cuốn sổ ấy thật cẩn thận.',
'Ngày Nhà giáo Việt Nam|Ngày 20 tháng 11 là ngày Nhà giáo Việt Nam.|Vào ngày này, học sinh cả nước tri ân thầy cô.|Lớp em chuẩn bị những bông hoa tươi và tiết mục văn nghệ.|Cô giáo xúc động cảm ơn tình cảm của cả lớp.',
'Dòng sông quê hương|Quê em có một dòng sông hiền hòa.|Mùa hè, nước sông trong xanh, lũ trẻ thường ra tắm mát.|Mùa lũ, nước sông dâng cao, đỏ ngầu phù sa.|Dòng sông đã bồi đắp nên những cánh đồng màu mỡ.|Em yêu dòng sông quê như yêu tuổi thơ mình.',
'Ích lợi của con trâu|Con trâu là người bạn thân thiết của nhà nông.|Trâu giúp người nông dân cày bừa ruộng đồng.|Trâu còn kéo xe chở lúa về nhà mỗi mùa gặt.|Với trẻ em nông thôn, lưng trâu là nơi gắn bó với nhiều kỉ niệm.',
'Một lần đi lạc|Năm em lên sáu, em theo mẹ đi chợ Tết.|Mải ngắm những con giống, em buông tay mẹ lúc nào không biết.|Khi quay lại, em không thấy mẹ đâu nữa.|May sao, một chú công an đã đưa em đến chỗ phát thanh của chợ.|Ít phút sau, mẹ chạy đến ôm chầm lấy em.',
'Vẻ đẹp của Sa Pa|Sa Pa là một thị trấn nằm trên núi cao.|Sáng sớm, mây trắng bồng bềnh phủ kín thung lũng.|Buổi trưa, nắng vàng chiếu sáng những ruộng bậc thang.|Về đêm, khí trời se lạnh, sương mù giăng khắp nơi.|Sa Pa luôn để lại ấn tượng khó quên với du khách.',
'Chăm sóc cây xanh|Lớp em được giao chăm sóc một bồn hoa trước cửa lớp.|Mỗi sáng, tổ trực nhật lại tưới nước cho cây.|Cuối tuần, chúng em nhổ cỏ và bón phân.|Nhờ được chăm sóc, bồn hoa lúc nào cũng tươi tốt.',
'Tình yêu quê hương|Ai cũng có một quê hương để nhớ về.|Quê hương là nơi ta sinh ra và lớn lên.|Ở đó có ông bà, cha mẹ và bao kỉ niệm tuổi thơ.|Dù đi đâu, ta vẫn luôn hướng về quê hương với niềm yêu thương.',
'Chiếc đồng hồ báo thức|Trên bàn học của em có một chiếc đồng hồ báo thức.|Đồng hồ có hình tròn, vỏ màu xanh lá cây.|Mặt đồng hồ có ba chiếc kim: kim giờ, kim phút và kim giây.|Mỗi sáng, tiếng chuông của nó đánh thức em dậy đi học.',
'Ý nghĩa của Tết Nguyên đán|Tết Nguyên đán là ngày Tết lớn nhất của người Việt.|Đây là dịp mọi người trong gia đình đoàn tụ.|Ngày Tết, con cháu chúc thọ ông bà và nhận lì xì.|Tết là dịp để mỗi người nhớ về cội nguồn và gửi gắm hi vọng cho năm mới.',
'Trường em|Trường em nằm ở trung tâm xã.|Ngôi trường có ba dãy nhà cao tầng khang trang.|Giữa sân trường là cột cờ cao và nhiều cây bóng mát.|Em rất yêu ngôi trường đã gắn bó với em năm năm qua.',
'Câu chuyện về chú ếch|Có một chú ếch sống lâu ngày trong một cái giếng.|Chú tưởng bầu trời chỉ bé bằng cái vung.|Một năm trời mưa to, nước giếng dâng lên đưa chú ra ngoài.|Quen thói cũ, chú nhâng nháo đi lại khắp nơi.|Cuối cùng, chú bị một con trâu giẫm bẹp.',
'Gió mùa đông bắc|Cuối tháng Mười, những đợt gió mùa đông bắc bắt đầu tràn về.|Trời trở lạnh, ai ra đường cũng phải mặc áo ấm.|Cây bàng trút lá, chỉ còn trơ những cành khẳng khiu.|Mùa đông đã thực sự đến rồi.',
'Bảo vệ động vật hoang dã|Động vật hoang dã là một phần quan trọng của thiên nhiên.|Thế nhưng, nhiều loài đang bị săn bắt trái phép.|Nếu không bảo vệ, chúng có thể bị tuyệt chủng.|Mỗi chúng ta hãy nói không với các sản phẩm từ động vật hoang dã.',
'Những ngày ôn thi|Gần đến kì thi cuối năm, em dành nhiều thời gian ôn bài.|Mỗi tối, em xem lại các bài toán khó.|Sau đó, em luyện viết một đoạn văn ngắn.|Trước khi ngủ, em đọc lại những ghi chép quan trọng.|Nhờ chăm chỉ, em tự tin bước vào kì thi.',
'Chú bé chăn trâu|Chiều chiều, chú bé dắt trâu ra bãi cỏ ven đê.|Trong khi trâu gặm cỏ, chú ngồi trên lưng trâu thổi sáo.|Tiếng sáo véo von vang khắp cánh đồng.|Mặt trời lặn, chú lại thong thả dắt trâu về.',
'Đêm giao thừa|Đêm giao thừa, cả nhà em quây quần bên mâm cỗ.|Đúng mười hai giờ, tiếng pháo hoa nổ vang trời.|Ông bà chúc con cháu năm mới mạnh khỏe, học giỏi.|Năm mới đã đến trong niềm vui của mọi người.',
'Hạt gạo|Hạt gạo trắng ngần là kết tinh của biết bao công sức.|Để có hạt gạo, người nông dân phải cày cấy, chăm bón suốt mấy tháng.|Từ hạt gạo, mẹ nấu thành những bát cơm thơm dẻo.|Vì vậy, chúng ta phải biết quý trọng từng hạt gạo.',
'Thả đèn hoa đăng|Đêm rằm, người dân phố cổ Hội An thả đèn hoa đăng trên sông.|Những chiếc đèn lung linh trôi theo dòng nước.|Mỗi chiếc đèn mang theo một lời ước nguyện.|Cả dòng sông như dát vàng dưới ánh đèn.',
'Chú chim sẻ|Sáng nào cũng có một chú chim sẻ đến đậu trên cành bàng.|Chú nhỏ xíu, lông màu nâu xám.|Chú nhảy nhót, lích chích tìm sâu.|Rồi chú vỗ cánh bay đi, để lại tiếng hót vui tai.',
'Vì sao cần ăn rau|Rau xanh là thực phẩm không thể thiếu trong bữa ăn.|Rau cung cấp nhiều vitamin và chất xơ cho cơ thể.|Ăn rau giúp ta tiêu hóa tốt và phòng nhiều bệnh.|Do đó, mỗi bữa ăn chúng ta nên có rau xanh.',
'Nắng sớm|Sáng sớm, nắng nhẹ nhàng len qua kẽ lá.|Những tia nắng vàng nhảy nhót trên mặt sân.|Nắng chiếu vào phòng, đánh thức em dậy.|Một ngày mới tràn đầy năng lượng đã bắt đầu.',
'Người ông kính yêu|Ông ngoại em từng là một người lính.|Ông đã tham gia nhiều trận đánh trong kháng chiến.|Giờ đây, ông sống giản dị, chăm chút từng cây cảnh trong vườn.|Em luôn kính trọng và học tập đức tính kiên cường của ông.',
'Đọc truyện cổ tích|Em rất thích đọc truyện cổ tích.|Truyện cổ tích đưa em vào thế giới kì diệu của bụt, tiên.|Qua mỗi câu chuyện, em học được bài học về lòng tốt.|Những câu chuyện ấy sẽ theo em suốt tuổi thơ.',
'Cánh đồng lúa chín|Tháng Năm, cánh đồng lúa quê em chín vàng.|Gió thổi, lúa nhấp nhô như sóng lượn.|Hương lúa chín thơm ngào ngạt khắp nơi.|Bà con nông dân phấn khởi chuẩn bị cho mùa gặt.',
'Chuẩn bị cho chuyến cắm trại|Thứ bảy này, lớp em sẽ đi cắm trại ở ngoại thành.|Từ đầu tuần, cả lớp đã chia thành các nhóm chuẩn bị.|Nhóm em phụ trách lều trại và dây buộc.|Tối thứ sáu, em kiểm tra lại đồ dùng một lần nữa rồi mới yên tâm đi ngủ.',
'Lá thư gửi bạn|Đã lâu rồi em không gặp Minh, người bạn thân chuyển vào Huế.|Tối qua, em quyết định viết thư cho bạn.|Trong thư, em kể về lớp học, về thầy cô và các bạn cũ.|Cuối thư, em hẹn hè này sẽ vào Huế thăm bạn.'
];

BANK['doc-hieu-nc']=[
'Mùa lũ năm ấy, nước dâng ngập cả con đường đến trường. Thầy Tâm chèo chiếc thuyền nhỏ đi đón từng học sinh. Có hôm thầy ướt sũng từ đầu đến chân, nhưng vẫn cười: “Chữ không chờ nước rút đâu các con ạ!”. Cuối năm, cả lớp không bạn nào phải bỏ học.||Vì sao thầy Tâm chèo thuyền đi đón học sinh?~Vì nước lũ ngập đường, học sinh không đến trường được.~Câu đầu cho biết nước dâng ngập con đường đến trường.~Vì thầy thích chèo thuyền.~Vì trường mở lớp học trên sông.#Câu “Chữ không chờ nước rút đâu các con ạ!” có ý gì?~Việc học rất quan trọng, không thể bỏ dở vì khó khăn.~Thầy muốn các em không bỏ lỡ việc học dù gặp lũ.~Nước lũ sẽ cuốn trôi sách vở.~Phải chờ nước rút mới học được.#Chi tiết “không bạn nào phải bỏ học” cho thấy điều gì?~Sự tận tụy của thầy đã giúp các em vượt qua khó khăn.~Đó là kết quả của việc thầy ngày ngày đưa đón học trò.~Năm đó không có lũ.~Lớp học có rất ít học sinh.',
'Bà cụ bán xôi đầu ngõ đã ngồi đó hơn hai mươi năm. Sáng nào cũng vậy, bà để riêng mấy gói xôi cho những đứa trẻ nhà nghèo. Bà bảo: “Ăn no mới học được, cháu ạ”. Có lần bà ốm, cả xóm thay nhau mang cháo đến thăm.||Bà cụ để riêng mấy gói xôi cho ai?~Cho những đứa trẻ nhà nghèo.~Câu thứ hai nói rõ điều này.~Cho khách quen.~Cho con cháu của bà.#Câu nói của bà cho thấy bà là người như thế nào?~Thương trẻ, mong các cháu được ăn no để học tốt.~Bà nghĩ đến việc học của các cháu.~Bà rất giàu có.~Bà muốn bán được nhiều xôi.#Vì sao khi bà ốm, cả xóm thay nhau đến thăm?~Vì bà sống tốt nên được mọi người yêu quý.~Tấm lòng tốt của bà được đền đáp.~Vì bà là người giàu nhất xóm.~Vì mọi người muốn mua xôi.',
'Trên cánh đồng khô hạn, một cây hoa nhỏ vẫn vươn lên giữa đất nứt nẻ. Mỗi sáng, nó uống từng giọt sương để sống. Đến khi mưa về, cả cánh đồng bừng lên sắc xanh, và bông hoa nhỏ là bông nở đầu tiên.||Cây hoa nhỏ sống bằng cách nào khi trời hạn?~Uống từng giọt sương mỗi sáng.~Câu thứ hai nói điều này.~Được người tưới nước.~Uống nước mưa.#Hình ảnh cây hoa nhỏ giúp em hiểu điều gì?~Phải kiên trì, mạnh mẽ vượt qua khó khăn.~Cây hoa vẫn sống giữa hạn hán và nở đầu tiên.~Cây hoa rất đẹp.~Đất nứt nẻ rất xấu.#Vì sao bông hoa nhỏ là bông nở đầu tiên?~Vì nó đã kiên cường sống sót và sẵn sàng khi mưa về.~Sự bền bỉ giúp nó đón cơ hội sớm nhất.~Vì nó to nhất.~Vì nó được trồng trước.',
'Nam được giao làm lớp trưởng. Lúc đầu, cậu hay ra lệnh và quát các bạn. Lớp vẫn ồn ào, chẳng ai nghe. Cô giáo khuyên: “Muốn các bạn nghe mình, em hãy làm gương trước”. Từ hôm đó, Nam đến lớp sớm nhất, nhặt rác, giúp bạn học yếu. Dần dần, cả lớp đều quý và nghe lời Nam.||Lúc đầu Nam quản lớp bằng cách nào?~Ra lệnh và quát các bạn.~Câu thứ hai nói rõ.~Làm gương cho các bạn.~Nhờ cô giáo quản lớp.#Lời khuyên của cô giáo có ý nghĩa gì?~Muốn người khác nghe theo, mình phải làm tốt trước.~“Làm gương trước” là tự mình làm đúng.~Phải quát to hơn.~Không cần quản lớp.#Bài học rút ra từ câu chuyện là gì?~Làm gương bằng việc làm có sức thuyết phục hơn lời ra lệnh.~Nam thay đổi cách làm và được các bạn quý.~Lớp trưởng phải nghiêm khắc.~Không nên làm lớp trưởng.',
'Ngày nào bố cũng dậy từ bốn giờ sáng để ra chợ đầu mối lấy hàng. Có hôm mưa to, bố về ướt sũng nhưng vẫn mỉm cười khi thấy em đã dậy học bài. Em hiểu, nụ cười ấy là phần thưởng lớn nhất mà em có thể tặng bố.||Bố dậy từ bốn giờ sáng để làm gì?~Ra chợ đầu mối lấy hàng.~Câu đầu nói rõ việc này.~Đi tập thể dục.~Đưa em đi học.#Vì sao bố mỉm cười dù bị ướt sũng?~Vì thấy con chăm chỉ học bài.~Sự chăm chỉ của con làm bố vui.~Vì bố thích đi mưa.~Vì bố bán được nhiều hàng.#Câu cuối thể hiện suy nghĩ gì của em?~Em hiểu sự chăm ngoan của mình làm bố vui, bù đắp vất vả.~Em coi nụ cười của bố là phần thưởng.~Em muốn được bố tặng quà.~Em không thích dậy sớm.',
'Ở bản Mù, lớp học chỉ có một gian nhà lợp lá. Mùa đông, gió lùa qua vách khiến tay các em tím tái. Cô giáo trẻ từ dưới xuôi lên đã nhóm một bếp lửa nhỏ giữa lớp. Quanh ngọn lửa, những bàn tay bé xíu lại hăng hái giơ lên phát biểu.||Lớp học ở bản Mù có đặc điểm gì?~Chỉ có một gian nhà lợp lá, gió lùa qua vách.~Câu một và câu hai tả lớp học.~Rất rộng rãi, có lò sưởi.~Được xây bằng gạch.#Cô giáo nhóm bếp lửa giữa lớp để làm gì?~Để sưởi ấm cho học trò trong mùa đông giá.~Gió lùa làm tay các em tím tái.~Để nấu cơm.~Để soi sáng lớp học.#Chi tiết “những bàn tay bé xíu lại hăng hái giơ lên phát biểu” cho thấy điều gì?~Tình thương của cô đã giúp các em vượt khó, say mê học tập.~Lớp học ấm áp hơn và học trò hăng hái hơn.~Các em bị lạnh nên giơ tay.~Các em muốn ra về.',
'Hai anh em chia nhau đống thóc. Đêm ấy, người anh nghĩ: “Em mới lập gia đình, còn nhiều thiếu thốn”, liền lặng lẽ bê thóc sang đống của em. Người em cũng nghĩ: “Anh có gia đình đông con”, nên bê thóc sang đống của anh. Sáng ra, hai đống thóc vẫn bằng nhau.||Vì sao người anh bê thóc sang đống của em?~Vì nghĩ em mới lập gia đình, còn thiếu thốn.~Lời nghĩ của người anh được nêu rõ.~Vì đống thóc của anh quá nhiều.~Vì người em nhờ anh.#Vì sao sáng ra hai đống thóc vẫn bằng nhau?~Vì cả hai anh em đều bê thóc sang cho nhau.~Mỗi người đều nghĩ cho người kia.~Vì có người đến lấy bớt.~Vì thóc tự mọc thêm.#Câu chuyện ca ngợi điều gì?~Tình anh em yêu thương, nhường nhịn nhau.~Ai cũng nghĩ cho người kia trước.~Sự giàu có.~Cách chia thóc công bằng.',
'Chiếc lá bàng cuối cùng còn bám trên cành. Gió bấc thổi mạnh, nó run lên nhưng không chịu rời cành. Mấy đứa trẻ ngước nhìn, đặt cược xem nó trụ được bao lâu. Ba ngày sau, những chồi non đã nhú bên cạnh chiếc lá già.||Chiếc lá bàng được tả ra sao trước gió bấc?~Run lên nhưng không chịu rời cành.~Câu thứ hai tả chiếc lá.~Rơi ngay xuống đất.~Bị gió cuốn đi xa.#Chi tiết “những chồi non đã nhú bên cạnh” có ý nghĩa gì?~Sự sống mới tiếp nối, chiếc lá già như chờ để trao lại.~Lá già và chồi non ở cạnh nhau.~Cây bàng sắp chết.~Trời đã sang hè.#Chiếc lá bàng trong bài tượng trưng cho điều gì?~Sự kiên cường, bền bỉ.~Không chịu rời cành dù gió mạnh.~Sự yếu ớt.~Sự lười biếng.',
'Minh mượn quyển truyện của Hùng và lỡ làm rách bìa. Minh định trả lại mà không nói gì. Nhưng nghĩ một lúc, Minh dán lại cẩn thận rồi mang trả và xin lỗi bạn. Hùng cười: “Cảm ơn cậu đã thật thà. Lần sau cứ mượn tiếp nhé!”.||Lúc đầu Minh định làm gì?~Trả lại mà không nói gì.~Câu thứ hai nói rõ.~Mua quyển mới.~Giấu quyển truyện đi.#Việc Minh dán lại và xin lỗi cho thấy Minh là người thế nào?~Thật thà, biết nhận lỗi.~Minh không giấu lỗi của mình.~Minh rất giàu.~Minh không thích đọc truyện.#Vì sao Hùng vẫn cho Minh mượn tiếp?~Vì Hùng quý sự thật thà của Minh.~Hùng nói lời cảm ơn vì Minh thật thà.~Vì quyển truyện đã cũ.~Vì Hùng không đọc nữa.',
'Cây cầu tre bắc qua con mương đầu làng đã có từ thời ông nội em. Mùa mưa, nước dâng cao, cầu chòng chành. Năm nay, cả làng góp tiền xây cầu bê tông. Ngày khánh thành, các cụ già đứng nhìn rất lâu, mắt rưng rưng.||Vì sao làng xây cầu bê tông?~Vì cầu tre cũ, mùa mưa chòng chành nguy hiểm.~Câu hai nói tình trạng cầu tre.~Vì cầu tre bị cháy.~Vì làng muốn có cầu to.#Các cụ già “mắt rưng rưng” vì sao?~Xúc động vì cây cầu mới và nhớ cây cầu cũ gắn bó bao năm.~Cầu tre có từ thời ông nội, nhiều kỉ niệm.~Vì bị gió bụi.~Vì các cụ không thích cầu mới.#Từ “chòng chành” tả điều gì?~Cây cầu lắc lư, không vững.~Mùa mưa nước dâng làm cầu rung lắc.~Cây cầu rất đẹp.~Cây cầu rất dài.',
'Bé Na nuôi một chú chim sẻ bị gãy cánh. Ngày nào bé cũng cho chim ăn, băng cánh cho nó. Đến khi chim khỏe, bé mở lồng. Chú chim bay vòng quanh sân ba lần rồi mới vụt lên trời xanh. Bé vẫy tay, vừa buồn vừa vui.||Bé Na chăm sóc chú chim thế nào?~Cho ăn và băng cánh mỗi ngày.~Câu thứ hai nói rõ.~Nhốt chim trong lồng mãi mãi.~Bán chú chim đi.#Chi tiết chú chim “bay vòng quanh sân ba lần” gợi điều gì?~Chim như lưu luyến, cảm ơn bé trước khi đi.~Chim chưa muốn rời xa ngay.~Chim bị lạc đường.~Chim chưa biết bay.#Vì sao bé “vừa buồn vừa vui”?~Buồn vì xa chim, vui vì chim được tự do.~Hai cảm xúc trái ngược cùng lúc.~Vì bé bị mẹ mắng.~Vì chim không quay lại ăn.',
'Đội tuyển bóng đá của trường em thua liền ba trận. Thầy huấn luyện viên không trách ai mà cho cả đội xem lại từng pha bóng. Cả đội nhận ra mình chơi rời rạc, ai cũng muốn tự ghi bàn. Từ trận sau, các cầu thủ chuyền bóng cho nhau nhiều hơn và giành chiến thắng.||Sau ba trận thua, thầy huấn luyện viên làm gì?~Cho cả đội xem lại từng pha bóng.~Thầy không trách mà giúp đội tự nhận ra lỗi.~Mắng cả đội.~Cho đội nghỉ tập.#Nguyên nhân đội thua là gì?~Chơi rời rạc, ai cũng muốn tự ghi bàn.~Câu thứ ba nói rõ nguyên nhân.~Đội bạn quá mạnh.~Trời mưa to.#Bài học rút ra là gì?~Đoàn kết, phối hợp với nhau thì sẽ thành công.~Đội thắng khi chuyền bóng cho nhau.~Phải tự mình ghi bàn.~Không nên chơi bóng đá.',
'Mỗi chiều, ông lão lại ngồi bên bờ hồ cho bầy cá ăn. Những người qua đường bảo ông phí công. Ông cười: “Tôi cho cá ăn để nhớ tuổi thơ, nhớ cái ao làng ngày xưa”. Từ đó, nhiều đứa trẻ trong phố cũng mang bánh mì đến cùng ông.||Ông lão làm gì mỗi chiều?~Cho bầy cá ăn bên bờ hồ.~Câu đầu nói rõ.~Câu cá.~Đi dạo quanh hồ.#Vì sao ông lão cho cá ăn?~Để nhớ tuổi thơ, nhớ ao làng xưa.~Ông giải thích trong câu nói của mình.~Để bán cá.~Vì ông chán.#Chi tiết “nhiều đứa trẻ cũng mang bánh mì đến” cho thấy điều gì?~Việc làm nhỏ của ông đã lan tỏa tình yêu thiên nhiên.~Bọn trẻ học theo ông.~Bọn trẻ đói.~Ông lão bán bánh mì.',
'Trên đỉnh núi đá cheo leo, cây thông mọc lên từ một khe nứt nhỏ. Không có đất màu, rễ thông phải luồn sâu vào đá để tìm nước. Gió bão quật mãi, thân thông cong vẹo nhưng chưa bao giờ gãy. Người leo núi thường dừng lại, chạm tay vào thân cây như để lấy thêm sức mạnh.||Rễ thông tìm nước bằng cách nào?~Luồn sâu vào đá.~Câu thứ hai nói rõ.~Hút nước từ đất màu.~Nhờ người tưới.#Thân thông “cong vẹo nhưng chưa bao giờ gãy” nói lên điều gì?~Sức chịu đựng, sự kiên cường trước thử thách.~Gió bão không làm cây gãy.~Cây thông rất yếu.~Cây thông sắp chết.#Vì sao người leo núi chạm tay vào thân cây?~Như muốn tiếp thêm nghị lực từ sự kiên cường của cây.~“Lấy thêm sức mạnh” là nghĩa bóng.~Để bẻ cành.~Vì thân cây rất mềm.',
'Lan sinh ra ở một làng chài nghèo. Mỗi tối, em ngồi học dưới ngọn đèn dầu leo lét. Năm ấy, Lan đạt giải Nhất học sinh giỏi cấp tỉnh. Hôm nhận giải, em chỉ nói: “Em cảm ơn ngọn đèn dầu và mẹ”.||Lan học bài trong điều kiện thế nào?~Dưới ngọn đèn dầu leo lét.~Câu thứ hai nói rõ.~Trong phòng học hiện đại.~Ở thư viện thành phố.#Vì sao Lan cảm ơn “ngọn đèn dầu và mẹ”?~Vì đó là những người, vật đã cùng em vượt khó học tập.~Ngọn đèn soi sáng, mẹ động viên em.~Vì ngọn đèn rất đẹp.~Vì mẹ mua đèn mới.#Câu chuyện muốn nói điều gì?~Ý chí vượt khó sẽ giúp ta thành công.~Hoàn cảnh nghèo nhưng Lan vẫn đạt giải cao.~Đèn dầu tốt hơn đèn điện.~Làng chài rất nghèo.',
'Sáng thứ hai, cả lớp phát hiện chậu hoa trước cửa bị đổ vỡ. Không ai nhận. Cô giáo không truy hỏi mà mua một chậu mới, đặt đúng chỗ cũ. Chiều hôm ấy, Tuấn ở lại, rụt rè nói với cô: “Thưa cô, em làm vỡ ạ”. Cô xoa đầu Tuấn: “Cô biết em sẽ nói mà”.||Cô giáo làm gì khi không ai nhận lỗi?~Mua chậu hoa mới đặt đúng chỗ cũ.~Cô không truy hỏi ai.~Phạt cả lớp.~Gọi phụ huynh lên.#Vì sao Tuấn quyết định nhận lỗi?~Vì cảm động trước cách cư xử bao dung của cô.~Cô không trách mắng khiến Tuấn hối hận.~Vì bị bạn mách.~Vì sợ bị phạt.#Câu nói “Cô biết em sẽ nói mà” thể hiện điều gì?~Cô tin tưởng vào sự trung thực của học trò.~Cô chờ đợi em tự nhận lỗi.~Cô đã nhìn thấy Tuấn làm vỡ.~Cô không quan tâm.',
'Hôm ấy, Mai đi học về thì thấy một cụ già đứng lúng túng bên đường đông xe. Mai đến gần, nhẹ nhàng hỏi rồi dắt cụ qua đường. Cụ cảm ơn, xoa đầu Mai. Về nhà, Mai kể cho mẹ nghe, mắt sáng lên niềm vui.||Mai đã làm việc tốt gì?~Dắt một cụ già qua đường đông xe.~Câu hai nói rõ.~Nhặt được của rơi.~Giúp bạn làm bài.#Vì sao mắt Mai “sáng lên niềm vui”?~Vì Mai hạnh phúc khi làm được việc tốt.~Niềm vui của người biết giúp đỡ người khác.~Vì được cụ cho quà.~Vì được nghỉ học.#Từ “lúng túng” tả trạng thái gì của cụ già?~Không biết xoay xở thế nào để qua đường.~Đường đông xe khiến cụ bối rối.~Rất vui vẻ.~Đang vội vàng.',
'Khi trận bão đi qua, cả xóm tan hoang. Nhà bác Tư bị tốc mái hoàn toàn. Sáng hôm sau, chưa ai bảo ai, những người hàng xóm đã mang tre, mang lá đến. Chỉ trong một buổi, ngôi nhà đã có mái mới.||Sau trận bão, nhà bác Tư bị làm sao?~Bị tốc mái hoàn toàn.~Câu hai nói rõ.~Bị ngập nước.~Bị đổ tường.#Cụm từ “chưa ai bảo ai” cho thấy điều gì?~Mọi người tự nguyện giúp đỡ, không cần nhắc nhở.~Tinh thần tương thân tương ái tự nhiên.~Mọi người không nói chuyện với nhau.~Mọi người bị bắt buộc.#Câu tục ngữ nào phù hợp với câu chuyện?~Lá lành đùm lá rách.~Câu chuyện nói về sự đùm bọc lúc khó khăn.~Có công mài sắt có ngày nên kim.~Ăn quả nhớ kẻ trồng cây.',
'Thỏ và Rùa lại thi chạy lần nữa. Lần này, Thỏ không dám chủ quan, chạy một mạch về đích. Rùa thua nhưng vẫn vui vẻ chúc mừng Thỏ. Thỏ bảo: “Nhờ cậu, tớ đã học được bài học quý”. Từ đó, hai bạn trở thành đôi bạn thân.||Lần thi này, Thỏ chạy như thế nào?~Không dám chủ quan, chạy một mạch về đích.~Câu hai nói rõ.~Ngủ quên giữa đường.~Chạy chậm như Rùa.#“Bài học quý” mà Thỏ nói đến là gì?~Không được chủ quan, kiêu ngạo.~Lần trước Thỏ thua vì chủ quan.~Phải chạy thật nhanh.~Không nên thi chạy.#Thái độ của Rùa khi thua cho thấy Rùa là người thế nào?~Biết chấp nhận thua cuộc, vui vẻ, rộng lượng.~Rùa chúc mừng Thỏ.~Rùa rất giận dữ.~Rùa kiêu ngạo.',
'Giữa sa mạc, người lữ khách gặp một cái giếng cạn. Bên cạnh có tấm bảng: “Hãy đổ chai nước này vào giếng để mồi máy bơm, rồi bơm nước uống thỏa thích. Sau đó, nhớ đổ đầy chai cho người sau”. Lữ khách khát cháy cổ nhưng vẫn làm theo. Nước mát trào lên. Uống xong, ông đổ đầy chai và đặt lại chỗ cũ.||Tấm bảng hướng dẫn người đi đường làm gì đầu tiên?~Đổ chai nước vào giếng để mồi máy bơm.~Câu thứ hai nói rõ.~Uống hết chai nước.~Mang chai nước đi.#Vì sao việc làm theo tấm bảng là khó?~Vì đang khát mà phải bỏ chai nước đi trước.~“Khát cháy cổ nhưng vẫn làm theo”.~Vì máy bơm hỏng.~Vì tấm bảng khó đọc.#Câu chuyện khuyên chúng ta điều gì?~Biết tin tưởng, cho đi và nghĩ đến người sau.~Ông đổ đầy chai cho người sau.~Phải giữ nước cho mình.~Không nên đi sa mạc.',
'Trong lớp em, Hoa là bạn ít nói nhất. Giờ ra chơi, bạn thường ngồi một mình đọc sách. Một hôm, em rủ Hoa chơi nhảy dây. Hoa ngập ngừng rồi gật đầu. Hóa ra Hoa nhảy rất giỏi và cười rất tươi. Từ đó, chúng em trở thành bạn thân.||Hoa thường làm gì trong giờ ra chơi?~Ngồi một mình đọc sách.~Câu hai nói rõ.~Chơi nhảy dây với các bạn.~Chạy nhảy ngoài sân.#Từ “ngập ngừng” cho thấy tâm trạng của Hoa thế nào?~Còn e dè, chưa mạnh dạn.~Hoa chần chừ trước khi đồng ý.~Rất vui vẻ.~Tức giận.#Câu chuyện gợi cho em điều gì?~Chủ động làm quen sẽ giúp ta có thêm bạn tốt.~Lời rủ của “em” đã mở đầu tình bạn.~Không nên chơi với bạn ít nói.~Đọc sách không có ích.',
'Bé Bin thích vẽ. Bé vẽ mặt trời màu xanh, cây cối màu tím. Các bạn cười bé. Cô giáo nhìn tranh rồi hỏi: “Vì sao con vẽ mặt trời màu xanh?”. Bin đáp: “Vì con muốn mặt trời mát mẻ hơn ạ”. Cô mỉm cười, treo bức tranh lên bảng lớp.||Vì sao các bạn cười Bin?~Vì Bin vẽ mặt trời màu xanh, cây màu tím, khác thường.~Màu sắc trong tranh không giống thực tế.~Vì Bin vẽ xấu.~Vì Bin không biết vẽ.#Câu trả lời của Bin cho thấy điều gì?~Bin có trí tưởng tượng phong phú và mong ước đẹp.~Bin muốn mặt trời bớt nóng.~Bin không biết màu sắc.~Bin muốn được khen.#Việc cô treo bức tranh lên bảng thể hiện điều gì?~Cô trân trọng sự sáng tạo của học trò.~Cô khuyến khích Bin.~Cô muốn các bạn cười Bin.~Cô không thích tranh.',
'Mỗi lần đi qua cánh đồng, ông lại nhặt những túi ni lông vương trên ruộng. Người làng hỏi sao ông chịu khó thế. Ông bảo: “Đất cũng như người, phải sạch thì mới khỏe”. Năm sau, cả làng cùng nhau tổ chức ngày thu gom rác.||Ông làm gì khi đi qua cánh đồng?~Nhặt những túi ni lông vương trên ruộng.~Câu đầu nói rõ.~Cày ruộng.~Thả diều.#Câu nói của ông có nghĩa là gì?~Đất cũng cần được giữ sạch thì mới tốt cho cây trồng.~Ông so sánh đất với người.~Người phải tắm rửa hằng ngày.~Đất rất bẩn.#Chi tiết “cả làng cùng nhau tổ chức ngày thu gom rác” cho thấy điều gì?~Việc làm của ông đã truyền cảm hứng cho mọi người.~Một người làm tốt, cả làng làm theo.~Làng có nhiều rác hơn.~Ông lão đã chuyển đi.',
'Chú lính chì chỉ có một chân. Bị rơi xuống rãnh nước, chú trôi qua bao nhiêu nguy hiểm mà vẫn đứng thẳng, tay cầm súng. Cuối cùng, chú được trở về và đứng đúng chỗ cũ trên bàn.||Chú lính chì có đặc điểm gì?~Chỉ có một chân.~Câu đầu nói rõ.~Có hai chân rất khỏe.~Không có tay.#Chi tiết “vẫn đứng thẳng, tay cầm súng” nói lên phẩm chất gì?~Dũng cảm, kiên cường trước nguy hiểm.~Dù gặp nguy hiểm chú vẫn giữ tư thế người lính.~Chú bị kẹt cứng.~Chú rất sợ hãi.#Câu chuyện nhắc nhở em điều gì?~Dù có khuyết điểm, ta vẫn có thể sống mạnh mẽ, dũng cảm.~Chú lính một chân vẫn kiên cường.~Đồ chơi bằng chì rất bền.~Không nên chơi gần rãnh nước.',
'Năm nay, bà ngoại em đã chín mươi tuổi. Bà không còn nhìn rõ, nhưng mỗi lần em về, bà vẫn nhận ra em qua giọng nói. Bà nắm tay em thật lâu, kể chuyện ngày em còn bé xíu, khóc nhè đòi bế. Em ngồi nghe, thấy mắt mình cay cay.||Bà nhận ra em bằng cách nào?~Qua giọng nói.~Bà không nhìn rõ nhưng vẫn nhận ra.~Qua khuôn mặt.~Qua quần áo.#Chi tiết “bà nắm tay em thật lâu” thể hiện điều gì?~Tình yêu thương, nỗi nhớ mong của bà dành cho cháu.~Bà không muốn rời cháu.~Bà muốn em đi về.~Tay bà bị lạnh.#Vì sao mắt em “cay cay”?~Em xúc động trước tình thương của bà.~Câu chuyện bà kể làm em cảm động.~Vì bị bụi bay vào mắt.~Vì em buồn ngủ.',
'Một chú kiến bị rơi xuống dòng suối. Chim bồ câu thấy vậy, thả một chiếc lá xuống. Kiến bám vào lá và vào được bờ. Ít lâu sau, một người thợ săn nhắm bắn bồ câu. Kiến bò đến, cắn vào chân hắn. Hắn giật mình, bồ câu bay thoát.||Chim bồ câu đã cứu kiến bằng cách nào?~Thả một chiếc lá xuống cho kiến bám vào.~Câu hai và ba nói rõ.~Bay xuống cõng kiến.~Gọi người đến cứu.#Kiến đã đền ơn bồ câu như thế nào?~Cắn vào chân người thợ săn để bồ câu bay thoát.~Hành động nhỏ của kiến cứu được bồ câu.~Mang thức ăn cho bồ câu.~Dẫn bồ câu về tổ.#Câu tục ngữ nào phù hợp với câu chuyện?~Ở hiền gặp lành.~Giúp người thì sẽ được người giúp lại.~Nước chảy đá mòn.~Tốt gỗ hơn tốt nước sơn.',
'Sáng nay, cô giáo cho cả lớp viết thư gửi một người mà mình muốn cảm ơn. Hà viết cho bác bảo vệ – người ngày nào cũng mở cổng sớm và dặn các bạn đi đứng cẩn thận. Khi nhận thư, bác bảo vệ đọc đi đọc lại, rồi cẩn thận gấp vào túi áo ngực.||Hà viết thư cảm ơn ai?~Bác bảo vệ của trường.~Câu thứ hai nói rõ.~Cô giáo chủ nhiệm.~Bố mẹ của Hà.#Vì sao Hà muốn cảm ơn người ấy?~Vì bác ngày nào cũng mở cổng sớm và dặn dò các bạn cẩn thận.~Sự quan tâm lặng lẽ của bác.~Vì bác cho Hà quà.~Vì bác dạy Hà học.#Hành động “cẩn thận gấp vào túi áo ngực” cho thấy điều gì?~Bác rất trân trọng và xúc động trước lá thư.~Bác giữ lá thư như một món quà quý.~Bác không thích lá thư.~Bác muốn vứt lá thư đi.',
'Đàn ngỗng bay về phương Nam thành hình chữ V. Con đầu đàn phải đón gió mạnh nhất. Khi mệt, nó lùi về sau và con khác lên thay. Nhờ vậy, cả đàn bay được rất xa mà không kiệt sức.||Đàn ngỗng bay theo hình gì?~Hình chữ V.~Câu đầu nói rõ.~Hình tròn.~Một hàng dọc.#Vì sao con đầu đàn phải thay nhau?~Vì con đầu đàn đón gió mạnh nhất, dễ mệt.~Thay nhau giúp không con nào kiệt sức.~Vì con đầu đàn bị lạc.~Vì con đầu đàn muốn nghỉ chơi.#Đàn ngỗng dạy chúng ta điều gì?~Đoàn kết, chia sẻ khó khăn thì sẽ đi được xa.~Cả đàn bay xa nhờ thay nhau dẫn đầu.~Phải luôn bay ở đầu.~Không nên bay xa.',
'Mùa hè năm ấy, cả xóm thiếu nước vì hạn hán. Nhà ông Ba có cái giếng sâu vẫn còn nước. Ông mở cổng, treo tấm biển: “Bà con cứ đến lấy nước, không phải trả tiền”. Suốt mùa hạn, sân nhà ông lúc nào cũng tấp nập người.||Vì sao cả xóm thiếu nước?~Vì hạn hán.~Câu đầu nói rõ.~Vì giếng bị lấp.~Vì mất điện.#Ông Ba đã làm gì?~Cho bà con đến lấy nước giếng miễn phí.~Ông treo biển mời mọi người.~Bán nước cho bà con.~Đóng cổng giữ nước.#Chi tiết “sân nhà ông lúc nào cũng tấp nập người” cho thấy điều gì?~Lòng tốt của ông đã giúp được rất nhiều người.~Nhiều người đến lấy nước.~Nhà ông mở tiệc.~Nhà ông có chợ.',
'Cậu bé hỏi ông: “Vì sao cây lúa lại cúi đầu?”. Ông đáp: “Bông lúa càng chắc hạt càng cúi thấp. Người càng hiểu biết càng khiêm tốn, cháu ạ”. Cậu bé nhìn cánh đồng, nghĩ mãi về câu nói ấy.||Theo ông, vì sao bông lúa cúi đầu?~Vì bông lúa càng chắc hạt càng nặng, cúi thấp.~Ông giải thích trong câu nói.~Vì bị gió thổi.~Vì lúa bị héo.#Ông muốn nhắn nhủ cháu điều gì?~Người càng hiểu biết càng phải khiêm tốn.~Ông so sánh người với bông lúa.~Phải trồng nhiều lúa.~Không nên hỏi nhiều.#Cậu bé “nghĩ mãi về câu nói ấy” cho thấy điều gì?~Câu nói của ông đã gợi cho cậu bé bài học sâu sắc.~Cậu suy ngẫm về lời ông.~Cậu không hiểu gì.~Cậu chán nghe ông nói.',
'Trên chuyến xe buýt đông người, một cậu bé đứng dậy nhường ghế cho bà bầu. Cả chuyến đi, cậu đứng bám tay vịn, lắc lư theo xe. Khi xuống xe, người mẹ trẻ cảm ơn cậu. Cậu bé đỏ mặt: “Mẹ cháu dặn phải nhường ghế cho người cần hơn ạ”.||Cậu bé đã làm việc tốt gì?~Nhường ghế cho bà bầu trên xe buýt.~Câu đầu nói rõ.~Giúp bà cụ xách đồ.~Nhặt được ví tiền.#Vì sao cậu bé làm như vậy?~Vì nhớ lời mẹ dặn phải nhường ghế cho người cần hơn.~Cậu nói rõ lí do khi được cảm ơn.~Vì muốn được khen.~Vì ghế bị hỏng.#Chi tiết “cậu bé đỏ mặt” cho thấy cậu là người thế nào?~Khiêm tốn, ngại ngùng khi được khen.~Cậu không coi việc tốt là điều to tát.~Cậu đang tức giận.~Cậu bị ốm.',
'Ngôi trường mới của bản được xây xong trước mùa mưa. Hôm khai giảng, già làng mặc bộ áo đẹp nhất, đánh tiếng chiêng khai trường. Lũ trẻ mặc váy áo sặc sỡ, chạy khắp các phòng học, sờ tay lên những bức tường còn mới.||Ngôi trường được xây xong vào lúc nào?~Trước mùa mưa.~Câu đầu nói rõ.~Sau Tết.~Giữa mùa đông.#Việc già làng mặc bộ áo đẹp nhất cho thấy điều gì?~Ngày khai trường là ngày rất trọng đại với cả bản.~Già làng coi trọng sự kiện này.~Già làng sắp đi xa.~Trời rất lạnh.#Hành động “sờ tay lên những bức tường còn mới” thể hiện cảm xúc gì của lũ trẻ?~Háo hức, vui sướng và trân trọng ngôi trường mới.~Các em ngắm nhìn từng chi tiết.~Lũ trẻ sợ hãi.~Lũ trẻ muốn về nhà.',
'Cuối năm học, lớp em tổ chức bỏ phiếu chọn bạn “Người bạn tốt”. Ai cũng nghĩ Nam học giỏi nhất sẽ được chọn. Nhưng kết quả lại là Tú, cậu bạn học trung bình. Cô giáo đọc những lá phiếu: “Tú luôn giúp mình khi mình buồn”, “Tú cho mình mượn áo mưa”…||Mọi người nghĩ ai sẽ được chọn?~Nam, bạn học giỏi nhất.~Câu thứ hai nói rõ.~Tú.~Cô giáo.#Vì sao Tú được chọn là “Người bạn tốt”?~Vì Tú luôn quan tâm, giúp đỡ các bạn.~Những lá phiếu kể về việc tốt của Tú.~Vì Tú học giỏi nhất.~Vì Tú là lớp trưởng.#Câu chuyện muốn nói điều gì?~Lòng tốt và sự quan tâm đáng quý không kém thành tích học tập.~Tú học trung bình nhưng được yêu quý.~Học giỏi là quan trọng nhất.~Không cần học giỏi.',
'Bà em trồng một cây mít trước ngõ từ khi mẹ em còn nhỏ. Bây giờ cây đã cao vượt mái nhà. Mùa mít chín, bà bổ mít mời cả xóm. Bà bảo: “Cây của nhà, nhưng quả là của mọi người”.||Cây mít được trồng từ bao giờ?~Từ khi mẹ em còn nhỏ.~Câu đầu nói rõ.~Năm ngoái.~Từ khi em còn nhỏ.#Câu nói của bà thể hiện điều gì?~Bà hào phóng, muốn chia sẻ với mọi người.~“Quả là của mọi người”.~Bà muốn bán mít.~Bà không thích ăn mít.#Chi tiết “cây đã cao vượt mái nhà” cho biết điều gì?~Cây mít đã được trồng rất lâu năm.~Cây lớn lên theo năm tháng.~Cây mít sắp đổ.~Mái nhà rất thấp.',
'Mấy hôm liền, chú công nhân điện lực trèo lên cột điện giữa trời mưa rét để sửa đường dây. Tối hôm ấy, khi đèn cả xóm sáng trở lại, lũ trẻ reo hò ầm ĩ. Chú đứng dưới chân cột, áo ướt sũng, mỉm cười nhìn những ô cửa sáng đèn.||Chú công nhân làm việc trong điều kiện thế nào?~Trèo cột điện giữa trời mưa rét.~Câu đầu nói rõ.~Trong phòng ấm áp.~Dưới trời nắng đẹp.#Vì sao lũ trẻ reo hò?~Vì cả xóm có điện trở lại.~Đèn sáng trở lại sau nhiều ngày.~Vì được nghỉ học.~Vì trời tạnh mưa.#Nụ cười của chú cho thấy điều gì?~Chú vui vì công sức của mình đã mang ánh sáng đến mọi nhà.~Niềm vui của người lao động khi hoàn thành công việc.~Chú thấy lạnh.~Chú muốn về nhà.'
];

